"use client";

import Link from "next/link";
import { usePathname } from "next/navigation";
import {
  LayoutDashboard,
  Globe,
  ShieldCheck,
  Mail,
  Bell,
  BarChart3,
  CreditCard,
  Settings,
  LogOut,
  Inbox,
  ChevronRight,
} from "lucide-react";

const NAV_SECTIONS = [
  {
    label: "MAIN",
    items: [
      { icon: LayoutDashboard, label: "Dashboard", href: "/dashboard" },
      { icon: Globe, label: "Domains", href: "/dashboard/domains" },
      { icon: ShieldCheck, label: "Compliance", href: "/dashboard/compliance" },
      { icon: Mail, label: "Unsubscribe", href: "/dashboard/unsubscribe" },
    ],
  },
  {
    label: "MONITOR",
    items: [
      { icon: Bell, label: "Alerts", href: "/dashboard/alerts", badge: 3 },
      { icon: BarChart3, label: "Analytics", href: "/dashboard/analytics" },
    ],
  },
  {
    label: "ACCOUNT",
    items: [
      { icon: CreditCard, label: "Billing", href: "/dashboard/billing" },
      { icon: Settings, label: "Settings", href: "/dashboard/settings" },
    ],
  },
];

export default function Sidebar() {
  const pathname = usePathname();

  function isActive(href: string) {
    if (href === "/dashboard") return pathname === "/dashboard";
    return pathname.startsWith(href);
  }

  return (
    <aside
      className="flex flex-col shrink-0"
      style={{
        width: 232,
        minWidth: 232,
        background: "#060D1F",
        borderRight: "1px solid rgba(255,255,255,0.05)",
      }}
    >
      {/* Brand */}
      <div
        className="flex items-center gap-3"
        style={{
          padding: "22px 18px",
          borderBottom: "1px solid rgba(255,255,255,0.05)",
        }}
      >
        <div
          className="flex items-center justify-center shrink-0"
          style={{
            width: 36,
            height: 36,
            borderRadius: 10,
            background: "linear-gradient(135deg, #2563EB 0%, #7C3AED 100%)",
            boxShadow: "0 4px 12px rgba(37,99,235,0.4)",
          }}
        >
          <Inbox size={17} color="white" strokeWidth={2.5} />
        </div>
        <div>
          <p
            style={{
              color: "white",
              fontWeight: 800,
              fontSize: 15.5,
              letterSpacing: "-0.3px",
              lineHeight: 1,
            }}
          >
            Inbox<span style={{ color: "#60A5FA" }}>Rules</span>
          </p>
          <p
            style={{
              color: "#1E3A5F",
              fontSize: 10,
              marginTop: 3,
              fontWeight: 500,
            }}
          >
            Compliance Platform
          </p>
        </div>
      </div>

      {/* Navigation */}
      <nav className="flex-1 overflow-y-auto" style={{ padding: "18px 10px" }}>
        {NAV_SECTIONS.map((section) => (
          <div key={section.label} style={{ marginBottom: 26 }}>
            <p
              style={{
                fontSize: 9.5,
                fontWeight: 700,
                letterSpacing: "0.1em",
                color: "#1E3A5F",
                padding: "0 10px",
                marginBottom: 6,
              }}
            >
              {section.label}
            </p>
            {section.items.map((item) => {
              const active = isActive(item.href);
              const Icon = item.icon;
              return (
                <Link
                  key={item.href}
                  href={item.href}
                  style={{
                    display: "flex",
                    alignItems: "center",
                    gap: 10,
                    padding: "9px 10px",
                    borderRadius: 10,
                    marginBottom: 2,
                    fontSize: 13,
                    fontWeight: active ? 600 : 500,
                    textDecoration: "none",
                    color: active ? "#FFFFFF" : "#3D5A80",
                    background: active
                      ? "linear-gradient(135deg, rgba(37,99,235,0.85) 0%, rgba(124,58,237,0.7) 100%)"
                      : "transparent",
                    boxShadow: active
                      ? "0 4px 12px rgba(37,99,235,0.25)"
                      : "none",
                    transition: "all 0.15s",
                  }}
                  onMouseEnter={(e) => {
                    if (!active) {
                      const el = e.currentTarget as HTMLAnchorElement;
                      el.style.background = "rgba(255,255,255,0.05)";
                      el.style.color = "#7FA3C8";
                    }
                  }}
                  onMouseLeave={(e) => {
                    if (!active) {
                      const el = e.currentTarget as HTMLAnchorElement;
                      el.style.background = "transparent";
                      el.style.color = "#3D5A80";
                    }
                  }}
                >
                  <Icon
                    size={15}
                    strokeWidth={active ? 2.5 : 2}
                    style={{ flexShrink: 0 }}
                  />
                  <span style={{ flex: 1 }}>{item.label}</span>
                  {"badge" in item && item.badge ? (
                    <span
                      style={{
                        background: "#EF4444",
                        color: "white",
                        fontSize: 10,
                        fontWeight: 700,
                        padding: "1px 6px",
                        borderRadius: 999,
                        lineHeight: 1.6,
                      }}
                    >
                      {item.badge}
                    </span>
                  ) : null}
                  {active && (
                    <ChevronRight size={12} style={{ opacity: 0.6 }} />
                  )}
                </Link>
              );
            })}
          </div>
        ))}
      </nav>

      {/* User */}
      <div
        style={{
          padding: "12px 10px",
          borderTop: "1px solid rgba(255,255,255,0.05)",
        }}
      >
        <div
          className="flex items-center gap-2.5 rounded-xl cursor-pointer"
          style={{ padding: "9px 10px" }}
        >
          <div
            style={{
              width: 34,
              height: 34,
              borderRadius: "50%",
              background: "linear-gradient(135deg, #2563EB, #7C3AED)",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              fontSize: 12,
              fontWeight: 700,
              color: "white",
              flexShrink: 0,
            }}
          >
            PO
          </div>
          <div style={{ flex: 1, minWidth: 0 }}>
            <p style={{ color: "#CBD5E1", fontSize: 13, fontWeight: 600 }}>
              Princewill O.
            </p>
            <p style={{ color: "#1E3A5F", fontSize: 11, marginTop: 1 }}>
              Pro Plan
            </p>
          </div>
          <LogOut size={14} color="#1E3A5F" />
        </div>
      </div>
    </aside>
  );
}
